"""class LRUCache:\n    def __init__(self,cap): self.cap=cap; self.cache={}; self.order=[]\n    def get(self,k):\n        if k in self.cache: self.order.remove(k); self.order.append(k); return self.cache[k]\n        return -1\n    def put(self,k,v):\n        if k in self.cache: self.order.remove(k)\n        elif len(self.order)>=self.cap: old=self.order.pop(0); del self.cache[old]\n        self.order.append(k); self.cache[k]=v\ncache=LRUCache(3); cache.put('a',1); cache.put('b',2); cache.put('c',3); cache.get('a'); cache.put('d',4); print(cache.get('b'),cache.get('c'),cache.get('d'))""",
